import type { HTMLAttributes, ReactNode } from 'react';
import { cn } from '@/lib/utils';

export function Disclosure({
  className,
  defaultOpen,
  summary,
  children,
}: {
  className?: string;
  defaultOpen?: boolean;
  summary: ReactNode;
  children: ReactNode;
}) {
  return (
    <details className={cn('group', className)} defaultOpen={defaultOpen}>
      <summary className="list-none cursor-pointer select-none">
        {summary}
      </summary>
      <div className="mt-2">{children}</div>
    </details>
  );
}

export function DisclosurePanel({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('rounded-lg border border-border bg-muted/10 p-3', className)} {...props} />;
}

